// Greedy reports whether this sampler is an argmax.
func (s *Sampler) Greedy() bool { return s == nil || s.Temp <= 0 }

// Sample picks a token from one row of logits.
func (s *Sampler) Sample(logits []float32) int32 {
	if s != nil {
		defer s.penalise(logits)()
	}
	if s.Greedy() {
		return Argmax(logits)
	}
	// The candidates, sorted by logit descending. A full sort of 248320 is
	// 30 ms and would be half a decode step, so the cut comes first: TopK
	// partitions, and TopP needs the order only over what survives it.
	k := s.TopK
	if k <= 0 || k > len(logits) {
		k = len(logits)
	}
	var idx []int32
	if k <= topKScan {
		// One pass, the k largest kept in order (P20f): the served default
		// is k = 20, and the quickselect below walked a 1 MB index array
		// over the row for ~2 ms a token — 5% of a decode step, and in a
		// speculative round, where the scheduler samples every verified
		// row in turn, twice or three times that.
		idx = topKOf(logits, k, s.topk[:0])
		s.topk = idx
	} else {
		idx = make([]int32, len(logits))
		for i := range idx {
			idx[i] = int32(i)
		}
		if k < len(idx) {
			// Partial: the k largest, in no particular order, then sorted.
			quickselect(logits, idx, k)
			idx = idx[:k]
		}
		sort.Slice(idx, func(a, b int) bool { return logits[idx[a]] > logits[idx[b]] })
	}

	// Softmax over the survivors, at temperature.
	maxL := logits[idx[0]]
	probs := make([]float32, len(idx))
	var sum float32
	for i, id := range idx {
		p := float32(math.Exp(float64((logits[id] - maxL) / s.Temp)))
		probs[i] = p
		sum += p
	}
	for i := range probs {
		probs[i] /= sum
	}

	if s.TopP > 0 && s.TopP < 1 {
		var acc float32
		for i := range probs {
			acc += probs[i]
			if acc >= s.TopP {
				probs, idx = probs[:i+1], idx[:i+1]
				break
			}
		}
		var re float32
		for _, p := range probs {
			re += p
		}
		for i := range probs {
			probs[i] /= re
		}
	}

	if s.MinP > 0 && s.MinP < 1 {
		// probs is sorted descending, so the survivors are a prefix.
		cut := s.MinP * probs[0]
		n := 1
		for n < len(probs) && probs[n] >= cut {
			n++
		}
		probs, idx = probs[:n], idx[:n]
		var re float32
		for _, p := range probs {
			re += p
		}
		for i := range probs {
			probs[i] /= re
		}
	}

	r := s.rng.Float32()
	var acc float32
	for i, p := range probs {
		acc += p
		if r < acc {
			return idx[i]
		}
	}
	return idx[len(idx)-1]
}

// Argmax is the greedy sampler, and the only one a comparison against
// llama.cpp uses. Ties go to the lowest id, which is what `ggml_argmax` does.
func Argmax(logits []float32) int32 {
	best, bestV := int32(0), float32(math.Inf(-1))
	for i, v := range logits {
// head's guesses for positions pos+1, pos+2, … — so guess k is compared
// against whatever the trunk's argmax at position pos+k turns out to be.
//
// The rewind is `Step`'s own: it sets `past` from the position it is given,
// and a KV cell past the end is masked out of every score, so the cells a
// rejected chain left behind are unreadable rather than stale and the next
// round overwrites the ones it needs. That is the whole of this head's
// rollback, and it is why P5a can measure the acceptance rate before P5c
// exists.
func (g *MTPHead) Chain(h []float32, embed *Model, first int32, pos, depth int, w Wiring, collapsed bool) ([]int32, error) {
	out := make([]int32, 0, depth)
	cur, state := first, h
	for k := 0; k < depth; k++ {
		e, err := embed.Embedding(cur)
		if err != nil {
			return nil, fmt.Errorf("llm: token_embd for the draft: %w", err)
		}
		logits, res, mixed, err := g.Step(state, e, pos+k, w)
		if err != nil {
			return nil, err
		}
