// draftArgmax is the draft's pick, over DraftVocab ids when it is set.
func (s *Speculator) draftArgmax(lg []float32) int32 {
	if s.DraftVocab > 0 && s.DraftVocab < len(lg) {
		lg = lg[:s.DraftVocab]
